import{d as h,C as e,o as g,c as d,j as n,a,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸·第13章","description":"《中庸》第 13 章——道不远人：忠恕违道不远，施诸己而不愿亦勿施于人；君子之道四，丘未能一。","frontmatter":{"title":"中庸·第13章","description":"《中庸》第 13 章——道不远人：忠恕违道不远，施诸己而不愿亦勿施于人；君子之道四，丘未能一。","category":"guide","aliases":["第13章","中庸第13章","道不远人"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-13.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-13.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-13.md"},b=h({...m,setup(p){const r=[{id:"buyuanr",label:"道不远人 · 以人治人",showLabel:!0,sentences:[["子曰：“道不远人。人之为道而远人，不可以为道。《诗》云：‘",{text:"伐柯",glossary:"fake"},"伐柯，其则不远。’执柯以伐柯，",{text:"睨",glossary:"ni"},"而视之，犹以为远。故君子",{text:"以人治人",glossary:"yirenzhiren"},"，",{text:"改而止",glossary:"gaierzhi"},"。"]],note:"「道不远人」——道并不远离人。「人之为道而远人，不可以为道」：若把道弄得远离人生，便不成其为道。引《诗》「伐柯伐柯，其则不远」——砍斧柄，样板就在手里；「执柯以伐柯，睨而视之，犹以为远」——拿着斧柄去砍斧柄，斜眼一瞥还嫌远。所以「君子以人治人，改而止」：以人的常道治人，改了便止。"},{id:"zhongshu",label:"忠恕违道不远 · 施诸己而不愿亦勿施于人",showLabel:!0,sentences:[[{text:"忠恕",glossary:"zhongshu"},{text:"违道不远",glossary:"weidao"},"，",{text:"施诸己而不愿",glossary:"shizhuji"},"，亦勿施于人。"]],note:"「忠恕违道不远」——尽己之谓忠，推己之谓恕，能忠能恕，离道就不远了。「施诸己而不愿，亦勿施于人」——加在自己身上不愿接受的，就不要加给别人。这是「恕」的正面界说。"},{id:"sidao",label:"君子之道四 · 庸德之行，言顾行",showLabel:!0,sentences:[["君子之道四，",{text:"丘",glossary:"qiu"},"未能一焉：所求乎子，以事父未能也；所求乎臣，以事君未能也；所求乎弟，以事兄未能也；所求乎朋友，先施之未能也。"],["庸德之行，庸言之谨，有所不足，不敢不勉，有余不敢尽；言顾行，行顾言，君子胡不",{text:"慥慥",glossary:"zaozao"},"尔！”"]],note:"孔子自责：「君子之道四，丘未能一焉」——君子之道有四条，我一条都没能做到：要求儿子事父，自己事父未能；要求臣事君，自己事君未能；要求弟事兄，自己事兄未能；要求朋友先施，自己先施未能。接着说「庸德之行，庸言之谨」：平常的德行要实行，平常的言语要谨慎；有所不足不敢不勉力，有余也不敢尽用；「言顾行，行顾言」——言顾及行、行顾及言，君子怎能不「慥慥」（笃实忠厚）呢！"}],t=[{id:"fake",term:"伐柯",pinyin:"fá kē",meaning:"砍制斧柄。柯：斧柄。《诗·豳风·伐柯》：「伐柯如之何？匪斧不克。」"},{id:"ni",term:"睨",pinyin:"nì",meaning:"斜视。朱注：「睨，邪视也。」执柯伐柯、睨而视之犹以为远——喻人总把道看得太远。"},{id:"yirenzhiren",term:"以人治人",pinyin:"yǐ rén zhì rén",meaning:"朱注：「即以其人之道，还治其人之身。」以人所本有、能知能行之道来要求他。"},{id:"gaierzhi",term:"改而止",pinyin:"gǎi ér zhǐ",meaning:"改了就不再追究。朱注：「其人能改，即止不治。」"},{id:"zhongshu",term:"忠恕",pinyin:"zhōng shù",meaning:"朱注：「尽己之心为忠，推己及人为恕。」"},{id:"weidao",term:"违道不远",pinyin:"wéi dào bù yuǎn",meaning:"离道不远。违：去、离，不是「违背」。"},{id:"shizhuji",term:"施诸己而不愿",pinyin:"shī zhū jǐ ér bù yuàn",meaning:"加在自己身上而不愿意的（事）。此即忠恕之事，与《论语》「己所不欲，勿施于人」同旨。"},{id:"qiu",term:"丘",pinyin:"qiū",meaning:"孔子自称其名。孔子名丘。"},{id:"zaozao",term:"慥慥",pinyin:"zào zào",meaning:"笃实的样子。朱注：「慥慥，笃实貌。」"}];return(y,i)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return g(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第13章",tabindex:"-1"},[a("中庸·第13章 "),n("a",{class:"header-anchor",href:"#中庸·第13章","aria-label":'Permalink to "中庸·第13章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,"第十三章说「道不远人」：道就在人身上，所以「以人治人」、以忠恕相待；末段列出「君子之道四」，孔子自谓一条也没做到。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),o(s,{colophon:"道不远人 · 忠恕 · 君子之道四",tone:"ink",sections:r,glossary:t,"default-mode":"slips","aria-label":"中庸·第13章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(l,{items:[{term:"伐柯",pinyin:["fá","kē"],meaning:"砍制斧柄。柯：斧柄。手执斧柄去砍斧柄，其法则就在手里。"},{term:"睨",pinyin:["nì"],meaning:"斜视。睨而视之犹以为远——喻人总把道看得太远。"},{term:"以人治人",pinyin:["yǐ","rén","zhì","rén"],meaning:"朱注：「即以其人之道，还治其人之身。」"},{term:"改而止",pinyin:["gǎi","ér","zhǐ"],meaning:"改了就不再追究。"},{term:"忠恕",pinyin:["zhōng","shù"],meaning:"尽己之心为忠，推己及人为恕。"},{term:"慥慥",pinyin:["zào","zào"],meaning:"笃实的样子。"}]}),i[4]||(i[4]=u("",23))])}}});export{z as __pageData,b as default};
